    throw new OAuthError(
      "invalid_request",
      "The authorization request expired or was already used",
    );
  }
  if (stored.user_id === null) {
    await database.query(
      `UPDATE authfn_oauth_authorization_requests
          SET user_id = $2
        WHERE id = $1 AND user_id IS NULL`,
      [stored.id, userId],
    );
  }
  return stored;
