      await database.query(
        `INSERT INTO authfn_oauth_client_redirect_uris (id, client_id, redirect_uri)
         VALUES ($1, $2, $3)`,
        [id("ocru_", runtime.randomBytes), registration.clientId, redirectUri],
      );
