      readBearerToken(
        new Request("https://mcp.skillplane.dev/mcp", {
          headers: { authorization: "Bearer spo_example" },
        }),
      ),
    ).toBe("spo_example");
    expect(
      readBearerToken(
        new Request("https://mcp.skillplane.dev/mcp?access_token=spo_example"),
      ),
    ).toBeUndefined();
  });
});

