import { randomBytes } from "node:crypto";
import { readFile } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import {
  readWorkerDevelopmentVariables,
  updateWorkerDevelopmentVariables,
} from "./lib/local-worker-vars.mjs";
import { isMain } from "./lib/production-deployment.mjs";

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const runtimePath = join(repoRoot, ".data", "local-runtime.json");
const turnstileTestSiteKey = "1x00000000000000000000AA";
const turnstileTestSecret = "1x0000000000000000000000000000000AA";

function generateSecret() {
  return randomBytes(48).toString("base64url");
}

function validateSecret(name, value) {
  if (typeof value !== "string" || value.length < 32 || new Set(value).size < 10) {
    throw new Error(`${name} must contain at least 32 characters of secret material`);
  }
  return value;
}

function existingOrGenerated(name, current, generated, retained) {
  if (current !== undefined) {
    retained.push(name);
    return validateSecret(name, current);
  }
  generated.push(name);
  return generateSecret();
}

export function selectSharedOAuthPepper(appValue, mcpValue, generated, retained) {
  if (appValue !== undefined && mcpValue !== undefined && appValue !== mcpValue) {
    throw new Error(
      "OAUTH_TOKEN_PEPPER differs between app/.dev.vars and mcp/.dev.vars",
    );
  }
  return existingOrGenerated(
    "OAUTH_TOKEN_PEPPER",
    appValue ?? mcpValue,
    generated,
    retained,
  );
}

export function selectTurnstileCredentials(siteKey, secretKey, generated, retained) {
  if ((siteKey === undefined) !== (secretKey === undefined)) {
    throw new Error(
      "PUBLIC_TURNSTILE_SITE_KEY and TURNSTILE_SECRET_KEY must be configured together",
    );
  }
  if (siteKey !== undefined && secretKey !== undefined) {
    if (siteKey.length < 10) {
      throw new Error("PUBLIC_TURNSTILE_SITE_KEY is invalid");
    }
    const officialTestPair =
      siteKey === turnstileTestSiteKey && secretKey === turnstileTestSecret;
    if (!officialTestPair) {
      validateSecret("TURNSTILE_SECRET_KEY", secretKey);
    }
    retained.push("PUBLIC_TURNSTILE_SITE_KEY", "TURNSTILE_SECRET_KEY");
    return { siteKey, secretKey };
  }
  generated.push("PUBLIC_TURNSTILE_SITE_KEY", "TURNSTILE_SECRET_KEY");
  return {
    siteKey: turnstileTestSiteKey,
    secretKey: turnstileTestSecret,
  };
}

async function readVariables(path) {
  try {
    return readWorkerDevelopmentVariables(await readFile(path, "utf8"));
  } catch (error) {
    if (error?.code === "ENOENT") return new Map();
    throw error;
  }
}

async function readRuntime() {
  let runtime;
  try {
    runtime = JSON.parse(await readFile(runtimePath, "utf8"));
  } catch (error) {
    if (error?.code === "ENOENT") {
      throw new Error("Local runtime is missing; run pnpm db:up first", {
        cause: error,
      });
    }
    throw new Error("Local runtime configuration is unreadable", { cause: error });
  }
  if (
    runtime?.port === undefined ||
    typeof runtime.databaseUrl !== "string" ||
    !runtime.databaseUrl.startsWith("postgres")
  ) {
    throw new Error("Local runtime configuration is invalid");
  }
  return runtime;
}

export async function initializeLocalEnvironment() {
  const runtime = await readRuntime();
  const appPath = join(repoRoot, "app", ".dev.vars");
  const mcpPath = join(repoRoot, "mcp", ".dev.vars");
  const [appVariables, mcpVariables] = await Promise.all([
    readVariables(appPath),
    readVariables(mcpPath),
  ]);
  const generated = [];
  const retained = [];
  const authfnSecret = existingOrGenerated(
    "AUTHFN_SECRET",
    appVariables.get("AUTHFN_SECRET"),
    generated,
    retained,
  );
  const oauthTokenPepper = selectSharedOAuthPepper(
    appVariables.get("OAUTH_TOKEN_PEPPER"),
    mcpVariables.get("OAUTH_TOKEN_PEPPER"),
    generated,
    retained,
  );
  const turnstile = selectTurnstileCredentials(
    appVariables.get("PUBLIC_TURNSTILE_SITE_KEY"),
    appVariables.get("TURNSTILE_SECRET_KEY"),
    generated,
    retained,
  );

  const databaseVariables = {
    RUNTIME_ENV: "local",
    DATABASE_ADAPTER: "postgres",
    DATABASE_URL: runtime.databaseUrl,
  };
  await updateWorkerDevelopmentVariables(appPath, {
    ...databaseVariables,
    AUTHFN_SECRET: authfnSecret,
    OAUTH_TOKEN_PEPPER: oauthTokenPepper,
    PUBLIC_TURNSTILE_SITE_KEY: turnstile.siteKey,
    TURNSTILE_SECRET_KEY: turnstile.secretKey,
  });
  await updateWorkerDevelopmentVariables(mcpPath, {
    ...databaseVariables,
    OAUTH_TOKEN_PEPPER: oauthTokenPepper,
  });

  return {
    ok: true,
    files: ["app/.dev.vars", "mcp/.dev.vars"],
    generated: [...new Set(generated)].sort(),
    retained: [...new Set(retained)].sort(),
    valuesPrinted: false,
    mode: "0600",
    defaultAuthentication: "disabled",
    authenticatedDevelopmentCommand: "pnpm dev:app:auth",
  };
}

if (isMain(import.meta.url)) {
  process.stdout.write(
    `${JSON.stringify(await initializeLocalEnvironment(), null, 2)}\n`,
  );
}
#!/usr/bin/env node

import { execFileSync } from "node:child_process";
import { randomBytes } from "node:crypto";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { createServer } from "node:net";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import {
  rebindLocalRuntimePort,
  selectLocalPostgresPort,
} from "./lib/local-postgres-port.mjs";
import { updateWorkerDevelopmentVariables } from "./lib/local-worker-vars.mjs";

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const dataDirectory = join(repoRoot, ".data");
const runtimePath = join(dataDirectory, "local-runtime.json");
const composePath = join(repoRoot, "docker-compose.yml");
const containerName = "skillplane-postgres";
const volumeName = "skillplane_postgres_data";
const image =
  "postgres:17-alpine@sha256:742f40ea20b9ff2ff31db5458d127452988a2164df9e17441e191f3b72252193";

function emit(payload) {
  process.stdout.write(`${JSON.stringify(payload, null, 2)}\n`);
}

function fail(code, message, exitCode, details = undefined) {
  process.stderr.write(
    `${JSON.stringify(
      {
        ok: false,
        code,
        message,
        ...(details === undefined ? {} : { details }),
      },
      null,
      2,
    )}\n`,
  );
  process.exit(exitCode);
}

function run(command, args, environment = process.env) {
  return execFileSync(command, args, {
    cwd: repoRoot,
    encoding: "utf8",
    env: environment,
    stdio: ["ignore", "pipe", "pipe"],
  }).trim();
}

function parsePort(value) {
  const port = Number(value);
  if (!Number.isInteger(port) || port < 1024 || port > 65_535) {
    fail(
      "POSTGRES_PORT_INVALID",
      "SKILLPLANE_POSTGRES_PORT must be an integer from 1024 to 65535",
      22,
    );
  }
  return port;
}

async function isPortAvailable(port) {
  return await new Promise((resolvePromise) => {
    const server = createServer();
    server.once("error", () => resolvePromise(false));
    server.listen({ host: "127.0.0.1", port, exclusive: true }, () => {
      server.close(() => resolvePromise(true));
    });
  });
}

function containerExists() {
  try {
    run("docker", ["inspect", containerName]);
    return true;
  } catch {
    return false;
  }
}

function containerIsRunning() {
  if (!containerExists()) {
    return false;
  }
  return (
    run("docker", ["inspect", "--format", "{{.State.Running}}", containerName]) ===
    "true"
  );
}

async function readRuntime() {
  try {
    const parsed = JSON.parse(await readFile(runtimePath, "utf8"));
    if (
      typeof parsed.port !== "number" ||
      typeof parsed.database !== "string" ||
      typeof parsed.user !== "string" ||
      typeof parsed.password !== "string" ||
      typeof parsed.databaseUrl !== "string"
    ) {
      fail("LOCAL_RUNTIME_INVALID", "Local runtime configuration is invalid", 24);
    }
    return parsed;
  } catch (error) {
    if (error?.code !== "ENOENT") {
      fail("LOCAL_RUNTIME_INVALID", "Local runtime configuration is unreadable", 24);
    }
    return null;
  }
}

function createRuntime(port) {
  const user = "skillplane_app";
  const database = "skillplane";
  const password = randomBytes(32).toString("base64url");
  const databaseUrl = `postgresql://${encodeURIComponent(user)}:${encodeURIComponent(
    password,
  )}@127.0.0.1:${port}/${database}`;
  const testDatabase = "skillplane_test";
  const testDatabaseUrl = `postgresql://${encodeURIComponent(user)}:${encodeURIComponent(
    password,
  )}@127.0.0.1:${port}/${testDatabase}`;
  return {
    port,
    database,
    testDatabase,
    user,
    password,
    databaseUrl,
    testDatabaseUrl,
  };
}

async function writeRuntime(runtime) {
  await mkdir(dataDirectory, { recursive: true, mode: 0o700 });
  await writeFile(runtimePath, `${JSON.stringify(runtime, null, 2)}\n`, {
    encoding: "utf8",
    mode: 0o600,
  });
}

async function writeWorkerDevelopmentVariables(runtime) {
  for (const workspace of ["app", "mcp"]) {
    await updateWorkerDevelopmentVariables(join(repoRoot, workspace, ".dev.vars"), {
      RUNTIME_ENV: "local",
      DATABASE_ADAPTER: "postgres",
      DATABASE_URL: runtime.databaseUrl,
    });
  }
}

let runtime = await readRuntime();
const requestedPort = parsePort(
  selectLocalPostgresPort(process.env.SKILLPLANE_POSTGRES_PORT, runtime?.port),
);
const persistedPort = runtime?.port;

if (runtime && runtime.port !== requestedPort) {
  if (process.env.SKILLPLANE_POSTGRES_PORT !== undefined) {
    fail(
      "POSTGRES_PORT_CONFIG_MISMATCH",
      "Configured port differs from the persisted Skillplane runtime",
      25,
      { variable: "SKILLPLANE_POSTGRES_PORT", persistedPort: runtime.port },
    );
  }
  runtime = rebindLocalRuntimePort(runtime, requestedPort);
}

runtime ??= createRuntime(requestedPort);

try {
  run("docker", ["version", "--format", "{{.Server.Version}}"]);
} catch {
  fail("DOCKER_UNAVAILABLE", "Docker engine is unavailable", 21);
}

const portChanged = persistedPort !== undefined && persistedPort !== runtime.port;
if ((portChanged || !containerIsRunning()) && !(await isPortAvailable(runtime.port))) {
  fail(
    "POSTGRES_PORT_OCCUPIED",
    `SKILLPLANE_POSTGRES_PORT ${runtime.port} is occupied`,
    23,
    { variable: "SKILLPLANE_POSTGRES_PORT", port: runtime.port },
  );
}

const composeEnvironment = {
  ...process.env,
  SKILLPLANE_POSTGRES_DATABASE: runtime.database,
  SKILLPLANE_POSTGRES_PASSWORD: runtime.password,
  SKILLPLANE_POSTGRES_PORT: String(runtime.port),
  SKILLPLANE_POSTGRES_USER: runtime.user,
};

try {
  run(
    "docker",
    [
      "compose",
      "--file",
      composePath,
      "up",
      "--detach",
      "--wait",
      "--wait-timeout",
      "60",
      "postgres",
    ],
    composeEnvironment,
  );
} catch {
  fail("POSTGRES_START_FAILED", "Postgres did not become healthy", 26);
}

await writeRuntime(runtime);
await writeWorkerDevelopmentVariables(runtime);

emit({
  ok: true,
  container: containerName,
  volume: volumeName,
  image,
  host: "127.0.0.1",
  port: runtime.port,
  database: runtime.database,
  user: runtime.user,
"}

