      if (registrationClientUri && registrationAccessToken) {
        const response = await fetch(registrationClientUri, {
          method: "DELETE",
          headers: { authorization: `Bearer ${registrationAccessToken}` },
          signal: AbortSignal.timeout(15_000),
        });
