      skills_list: inventory.tools.some((tool) => tool.name === "skills_list"),
      skill_retrieve: inventory.tools.some((tool) => tool.name === "skill_retrieve"),
    },
    workspaces: {
      returned: workspaceResult.workspaces?.length ?? 0,
      slugs: (workspaceResult.workspaces ?? []).map((workspace) => workspace.slug),
      hasNextPage: Boolean(workspaceResult.nextCursor),
    },
    skillsList: skillEvidence,
    skillRetrieve: retrieveEvidence,
  }, null, 2));
} finally {
  await client.close().catch(() => {});
}
