import { execFileSync } from "node:child_process";
import { randomUUID } from "node:crypto";
import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StreamableHTTPClientTransport } from "@modelcontextprotocol/sdk/client/streamableHttp.js";

const raw = execFileSync("security", ["find-generic-password","-s","Codex MCP Credentials","-a","skillplane_local_-for_testing_only-|3745aac2f7635e7e","-w"], {encoding:"utf8"});
const credential = JSON.parse(raw);
const client = new Client({name:"codex-local-skillplane-check",version:"1.0.0"});
const transport = new StreamableHTTPClientTransport(new URL(credential.url), {requestInit:{headers:{authorization:`Bearer ${credential.token_response.access_token}`}}});
const caller = {
  agentId:"codex-local-check",agentName:"Codex",modelProvider:"openai",modelName:"gpt-5",modelVersion:"current",
  clientName:"Codex Desktop",clientVersion:"current",runId:`run:${randomUUID()}`,
  sessionId:`session:${randomUUID()}`,conversationId:`conversation:${randomUUID()}`
};
const jsonText = (result) => {
  const text = result.content?.find((item)=>item.type==="text")?.text;
  return typeof text === "string" ? JSON.parse(text) : null;
};
try {
  await client.connect(transport);
  const inventory = await client.listTools();
  const workspacesCall = await client.callTool({name:"workspaces_list",arguments:{caller,cursor:null,limit:10}});
  const workspaces = jsonText(workspacesCall);
  const firstWorkspace = workspaces?.workspaces?.[0];
  const skillsCall = await client.callTool({name:"skills_list",arguments:{caller,workspace:{slug:firstWorkspace.slug},cursor:null,limit:5,state:"active"}});
  const skills = jsonText(skillsCall);
  const firstSkill = skills?.skills?.find((skill)=>skill.currentVersion);
  const retrieveCall = await client.callTool({name:"skill_retrieve",arguments:{caller,skill:{workspaceSlug:firstSkill.workspaceSlug,skillSlug:firstSkill.slug},version:{selector:"current"}}});
  const retrieve = jsonText(retrieveCall);
  console.log(JSON.stringify({
    endpoint:credential.url,
    server:client.getServerVersion?.() ?? null,
    toolCount:inventory.tools.length,
    workspaces:{isError:workspacesCall.isError===true,returned:workspaces?.workspaces?.length ?? 0,slugs:(workspaces?.workspaces ?? []).map((x)=>x.slug)},
    skillsList:{isError:skillsCall.isError===true,workspace:skills?.workspace?.slug ?? null,returned:skills?.skills?.length ?? 0,firstSkill:firstSkill ? {slug:firstSkill.slug,semanticVersion:firstSkill.currentVersion?.semanticVersion ?? null}:null},
    skillRetrieve:{isError:retrieveCall.isError===true,response:retrieve},
  },null,2));
} finally {
  await client.close().catch(()=>{});
}
