  {step:"Integrate the fix onto latest origin/main and push main safely",status:"pending"},
  {step:"Run release gates from the exact pushed main commit",status:"pending"},
  {step:"Deploy and verify app and MCP in dev",status:"pending"},
  {step:"Deploy and verify app and MCP in production",status:"pending"},
  {step:"Clean up temporary deployment state and report exact evidence",status:"pending"}
]});
