  tools.exec_command({cmd:"git status --short --branch --untracked-files=all\ngit rev-parse HEAD\ngit branch --show-current\ngit diff --stat\ngit diff --check",workdir:cwdFix,yield_time_ms:10000,max_output_tokens:16000}),
  tools.exec_command({cmd:"rg -n '\"(deploy|verify|test|build|typecheck|db:backup|db:migrate)[^\"]*\"' package.json */package.json\nrg -n \"deploy:(app|mcp)|production-smoke|dev.*deploy|deploy.*dev|backup:production|migrate:production\" README.md docs scripts package.json .github 2>/dev/null | head -240",workdir:cwdMain,yield_time_ms:10000,max_output_tokens:24000}),
