    console.error(
      JSON.stringify({
        component: "mcp",
        event: "mcp.posthog.flush.failed",
      }),
    );
  };
  let flush: Promise<void>;
  try {
    flush = Promise.resolve(posthog.flush()).catch(reportFailure);
