function epsilonClosure(automaton: TemplateAutomaton, initial: number): Set<number> {
  const closure = new Set([initial]);
  const queue = [initial];
  while (queue.length) {
    const state = queue.shift()!;
    for (const next of automaton.states[state]!.epsilon) {
