      "Resource template",
      definition.name,
      definition.subscribe,
      definition.unsubscribe,
    );
    if ([...this.resourceTemplates.values()].some(
      ({ definition: registered }) =>
        uriTemplatesOverlap(registered.uriTemplate, definition.uriTemplate),
    )) {
