}

function anchoredLiteralSuffix(pattern: string): string | undefined {
  if (!pattern.endsWith("$") || pattern.endsWith("\\$")) return undefined;
  let suffix = "";
  for (let index = 0; index < pattern.length - 1; index += 1) {
