export async function resolveSkill(
  runtime: McpToolRuntime,
  execution: ToolExecution,
  selector: SkillSelector,
  options: {
    readonly action:
      | "skills:read"
      | "skills:write"
      | "skills:amend"
      | "skills:publish"
      | "contexts:read"
