  if (!row || (row.archived_at && !options.allowArchived)) {
    throw new McpToolError("CONTEXT_NOT_FOUND", "The context was not found", {
      status: 404,
    });
  }
  execution.setScope({
    resourceType: "context",
    resourceId: row.id,
    contextId: row.id,
  });
