export function uriTemplateMatchShape(uriTemplate: string): string {
  return uriTemplate.replace(/\{([^{}]+)\}/g, (_match, expression: string) => {
    const operator = /^[+#./?&]/.exec(expression)?.[0] ?? "";
    if (operator === "?" || operator === "&") {
      const names = expression.slice(1)
        .split(",")
